from django.urls import pathfrom . import viewsurlpatterns = [    path('', views.HomeView.as_view(), name='home'),    path('room/<int:pk>/', views.RoomDetailView.as_view(), name='room_detail'),    path('api/bookings/<int:room_id>/', views.get_bookings, name='get_bookings'), # JSON用    path('api/bookings/create/', views.CreateBookingView.as_view(), name='create_booking'),]